package java.util.concurrent;
import java.util.*;
public class LinkedBlockingDeque<E> extends AbstractQueue<E> implements BlockingDeque<E>,java.io.Serializable {
 private final LinkedList<E> q=new LinkedList<E>(); private final int capacity;
 public LinkedBlockingDeque(){this(Integer.MAX_VALUE);} public LinkedBlockingDeque(int capacity){if(capacity<=0)throw new IllegalArgumentException();this.capacity=capacity;} public LinkedBlockingDeque(Collection<? extends E> c){this();addAll(c);}
 public int size(){return q.size();} public int remainingCapacity(){return capacity-size();} public Iterator<E> iterator(){return q.iterator();} public Iterator<E> descendingIterator(){return q.descendingIterator();}
 public boolean offerFirst(E e){if(e==null)throw new NullPointerException();if(size()==capacity)return false;q.addFirst(e);return true;} public boolean offerLast(E e){if(e==null)throw new NullPointerException();if(size()==capacity)return false;q.addLast(e);return true;}
 public void addFirst(E e){if(!offerFirst(e))throw new IllegalStateException("Deque full");} public void addLast(E e){if(!offerLast(e))throw new IllegalStateException("Deque full");} public boolean offer(E e){return offerLast(e);} public boolean add(E e){addLast(e);return true;}
 public E pollFirst(){return q.pollFirst();} public E pollLast(){return q.pollLast();} public E removeFirst(){return q.removeFirst();} public E removeLast(){return q.removeLast();} public E getFirst(){return q.getFirst();} public E getLast(){return q.getLast();} public E peekFirst(){return q.peekFirst();} public E peekLast(){return q.peekLast();} public E poll(){return pollFirst();} public E peek(){return peekFirst();} public void push(E e){addFirst(e);} public E pop(){return removeFirst();} public boolean removeFirstOccurrence(Object o){return o!=null&&q.removeFirstOccurrence(o);} public boolean removeLastOccurrence(Object o){return o!=null&&q.removeLastOccurrence(o);} public boolean remove(Object o){return removeFirstOccurrence(o);}
 public void putFirst(E e)throws InterruptedException {if(!offerFirst(e)){java.lang.VMThread.runPending();if(!offerFirst(e))throw new IllegalStateException("Deque full");}} public void putLast(E e)throws InterruptedException {if(!offerLast(e)){java.lang.VMThread.runPending();if(!offerLast(e))throw new IllegalStateException("Deque full");}} public void put(E e)throws InterruptedException{putLast(e);}
 public boolean offerFirst(E e,long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();if(offerFirst(e))return true;java.lang.VMThread.runPending();return offerFirst(e);} public boolean offerLast(E e,long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();if(offerLast(e))return true;java.lang.VMThread.runPending();return offerLast(e);} public boolean offer(E e,long n,TimeUnit u)throws InterruptedException{return offerLast(e,n,u);}
 public E takeFirst()throws InterruptedException{E e=pollFirst();if(e==null){java.lang.VMThread.runPending();e=pollFirst();}return e;} public E takeLast()throws InterruptedException{E e=pollLast();if(e==null){java.lang.VMThread.runPending();e=pollLast();}return e;} public E take()throws InterruptedException{return takeFirst();} public E pollFirst(long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();return takeFirst();} public E pollLast(long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();return takeLast();} public E poll(long n,TimeUnit u)throws InterruptedException{return pollFirst(n,u);}
 public int drainTo(Collection<? super E> c){return drainTo(c,Integer.MAX_VALUE);} public int drainTo(Collection<? super E> c,int max){if(c==null)throw new NullPointerException();if(c==this)throw new IllegalArgumentException();int n=0;while(n<max&&!q.isEmpty()){c.add(q.peekFirst());q.removeFirst();n++;}return n;}
}